  example zip_sum([], []) == []
  example zip_sum([5], [-5]) == [0]
{
  match xs {
    [] => []
    [h, ..t] => match ys {
      [] => []
      [h2, ..t2] => [h + h2, ..zip_sum(t, t2)]
    }
  }
}

